class TimeoutException(Exception):
    pass


class TooManyFilesFoundException(Exception):
    pass


class OutOfRange(Exception):
    pass


class AttributeDoesNotExist(Exception):
    """
    Raises when HTML Table class cannot find proper attribute
    in table object.
    """
    pass


class CouldNotFindObject(Exception):
    """
    Raises when HTML Table class cannot find table object
    with given xpath.
    """
    pass


class DegeneratedTable(Exception):
    """
    Raises when table object found by HTML Table class does not
    have any columns and rows.
    """
    pass


class ColumnDoesNotExist(Exception):
    """
    Raises when some method from HTML Table class cannot find
    column with given name as an argument.
    """
    pass
